private val parsedSmartAudioCopies = HashMap<String, SmartAudioCopy>()

internal fun smartAudioCopy(code: String): SmartAudioCopy = synchronized(parsedSmartAudioCopies) {
    parsedSmartAudioCopies.getOrPut(code) {
        val raw = localizedValueOrEnglish(smartAudioBundles, code)
        SmartAudioCopy(raw.split('|'))
    }
}

internal fun smartAudioLocalizationCodes(): Set<String> = smartAudioBundles.keys

internal fun smartAudioRawEntries(code: String): List<String> = smartAudioBundles.getValue(code).split('|')
